def build_faculty_form(tokens,on_submit,on_cancel,record=None,departments=None):
    record=record or {}; create=not record
    specs=[("display_name","Full name"),("employee_id","Employee ID"),("email","Email"),("username","Username"),("temporary_password","Temporary password"),("phone","Phone"),("department_id","Department ID"),("designation","Designation"),("joining_date","Joining date (YYYY-MM-DD)")]
    fields={n:ft.TextField(label=l,value=str(record.get(n) or ""),password=n=="temporary_password",can_reveal_password=n=="temporary_password",visible=create or n not in {"employee_id","username","temporary_password"}) for n,l in specs}
    if departments: fields["department_id"]=ft.Dropdown(label="Department",value=str(record.get("department_id") or "") or None,options=[ft.DropdownOption(key=str(x.get("_id")),text=f"{x.get('code','')} · {x.get('name','Department')}") for x in departments],enable_search=True)
    return ft.Container(ft.Column([page_header("Add Faculty" if create else "Edit Faculty","Account credentials remain separate from the Faculty profile.",tokens),ft.ResponsiveRow([ft.Container(x,col={"xs":12,"md":6}) for x in fields.values()]),ft.Row([ft.TextButton("Cancel",on_click=on_cancel),ft.FilledButton("Save Faculty",on_click=lambda _:on_submit({k:v.value for k,v in fields.items() if v.visible and v.value}))],alignment=ft.MainAxisAlignment.END)],spacing=12,scroll=ft.ScrollMode.AUTO),width=720,height=620,padding=8)

def build_assignment_form(tokens,on_submit,on_cancel,options=None):
    options=options or {}; years=options.get("years",[]); classes=options.get("classes",[]); subjects=options.get("subjects",[])
    year=ft.Dropdown(label="Academic Year",options=[ft.DropdownOption(key=str(x.get("_id")),text=x.get("name","Academic Year")) for x in years]); division=ft.Dropdown(label="Class / Division",disabled=True); subject=ft.Dropdown(label="Subject",disabled=True)
    def year_changed(_):
        division.options=[ft.DropdownOption(key=str(x.get("_id")),text=f"{x.get('name','Class')} · {x.get('division','')}") for x in classes if str(x.get("academic_year_id"))==str(year.value)];division.value=None;division.disabled=False;subject.value=None;subject.options=[];subject.disabled=True;division.update();subject.update()
    def class_changed(_):
        selected=next((x for x in classes if str(x.get("_id"))==str(division.value)),{});subject.options=[ft.DropdownOption(key=str(x.get("_id")),text=f"{x.get('code','')} · {x.get('name','Subject')}") for x in subjects if str(x.get("program_id"))==str(selected.get("program_id")) and str(x.get("semester_id"))==str(selected.get("semester_id"))];subject.value=None;subject.disabled=False;subject.update()
    year.on_select=year_changed;division.on_select=class_changed
    start=ft.TextField(label="Start date (optional)");end=ft.TextField(label="End date (optional)");kind=ft.Dropdown(label="Assignment type",value="primary",options=[ft.DropdownOption(key=x,text=x.replace("_"," ").title()) for x in ("primary","co_faculty","practical","project_guide")])
    return ft.Container(ft.Column([page_header("Assign Subject","Academic Year → Class → Subject selection is hierarchy-aware.",tokens),year,division,subject,start,end,kind,ft.Text("Only Subjects matching the selected Class Program and Semester are offered and accepted.",size=11,color=tokens["text_secondary"]),ft.Row([ft.TextButton("Cancel",on_click=on_cancel),ft.FilledButton("Confirm Assignment",on_click=lambda _:on_submit({k:v for k,v in {"academic_year_id":year.value,"class_division_id":division.value,"subject_id":subject.value,"start_date":start.value,"end_date":end.value,"assignment_type":kind.value}.items() if v}))],alignment=ft.MainAxisAlignment.END)],spacing=10,scroll=ft.ScrollMode.AUTO),width=620,height=590,padding=8)

