    account=record.get("account") or {}; assignments=record.get("assignments") or []
    assignment_rows=[ft.Text(f"{x.get('assignment_type','—').replace('_',' ').title()} · {(x.get('subject') or {}).get('name',x.get('subject_id','—'))} · {(x.get('class_division') or {}).get('name',x.get('class_division_id','—'))} · {x.get('status','—')}",size=12) for x in assignments]
    return ft.Container(ft.Column([page_header(record.get("display_name","Faculty"),"Profile, account state, and teaching ownership.",tokens),surface_card(ft.Column([ft.Text(f"Employee ID: {record.get('employee_id','—')}"),ft.Text(f"Email: {record.get('email','—')}"),ft.Text(f"Designation: {record.get('designation','—')}"),ft.Text(f"Department: {(record.get('department') or {}).get('name',record.get('department_id','—'))}"),ft.Text(f"Account: {account.get('status','—')}")],spacing=8),tokens),surface_card(ft.Column([ft.Text("Teaching Assignments",weight=ft.FontWeight.BOLD),*(assignment_rows or [ft.Text("No active teaching assignments.")])],spacing=8),tokens),empty_state("Schedule unavailable","Schedule becomes available after timetable setup.",ft.Icons.CALENDAR_MONTH_OUTLINED,tokens),ft.Row([ft.FilledButton("Close",on_click=on_close)],alignment=ft.MainAxisAlignment.END)],spacing=12,scroll=ft.ScrollMode.AUTO),width=720,height=650,padding=8)
